-- Disposable end-to-end staff assistant fixtures. Rollback leaves no accounts, bookings or sessions.
BEGIN;
CREATE FUNCTION pg_temp.sa_assert(ok boolean,label text)RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'STAFF AGENT TEST FAILED: %',label;END IF;END $$;
DO $$
DECLARE c uuid:=gen_random_uuid();m uuid:=gen_random_uuid();h uuid:=gen_random_uuid();u uuid:=gen_random_uuid();
 cs text;ms text;hs text;venue text;task uuid;pid text;sid text;bid text;res jsonb;again jsonb;item jsonb;q jsonb;ver int;denied bool;before_hash text;after_hash text;
BEGIN
 SELECT md5(COALESCE(jsonb_agg(to_jsonb(a)ORDER BY experience_id,month,week)::text,''))INTO before_hash FROM journey_hub.activity_weekly_stats a;
 INSERT INTO auth.users(id,email,raw_user_meta_data)VALUES(c,'staff-agent-'||c||'@example.invalid','{}'),(m,'staff-agent-'||m||'@example.invalid','{}'),(h,'staff-agent-'||h||'@example.invalid','{}'),(u,'staff-agent-'||u||'@example.invalid','{}');
 SELECT venue_id INTO venue FROM journey_hub.experiences WHERE experience_id='craft';
 LOOP cs:='AC-'||(1000+floor(random()*9000)::int);EXIT WHEN NOT EXISTS(SELECT 1 FROM journey_hub.staff WHERE staff_id=cs);END LOOP;
 LOOP ms:='AM-'||(1000+floor(random()*9000)::int);EXIT WHEN NOT EXISTS(SELECT 1 FROM journey_hub.staff WHERE staff_id=ms);END LOOP;
 LOOP hs:='AH-'||(1000+floor(random()*9000)::int);EXIT WHEN NOT EXISTS(SELECT 1 FROM journey_hub.staff WHERE staff_id=hs);END LOOP;
 INSERT INTO journey_hub.staff(staff_id,display_name,role,venue_id,pin_hash,auth_user_id)VALUES(cs,'Assistant QA coordinator','coordinator',venue,'disabled',c),(ms,'Assistant QA manager','duty_manager',venue,'disabled',m),(hs,'Assistant QA host','host',venue,'disabled',h);
 -- Isolate the rollback fixture recommendation from any saved real staff task.
 UPDATE journey_hub.staff_agent_tasks SET task_key='qa-saved-'||id WHERE task_key='next-craft-session';
 PERFORM pg_temp.sa_assert(NOT has_function_privilege('anon','public.journeyhub_staff_agent(text,uuid)','EXECUTE'),'anonymous RPC denied');
 PERFORM pg_temp.sa_assert(NOT has_function_privilege('authenticated','journey_hub.staff_agent_scan()','EXECUTE'),'background scanner is private');
 PERFORM pg_temp.sa_assert(NOT has_table_privilege('authenticated','journey_hub.staff_agent_tasks','SELECT'),'tasks are only exposed by role-checked RPC');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u)::text,true);denied:=false;
 BEGIN PERFORM public.journeyhub_staff_agent('list',NULL);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 PERFORM pg_temp.sa_assert(denied,'traveler cannot read staff operations');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',c)::text,true);
 res:=public.journeyhub_staff_agent('refresh',NULL);SELECT id INTO task FROM journey_hub.staff_agent_tasks WHERE task_key='next-craft-session';
 PERFORM pg_temp.sa_assert(task IS NOT NULL,'scan creates one future scenario');
 res:=public.journeyhub_staff_agent('prepare',task);pid:=res->>'planId';again:=public.journeyhub_staff_agent('prepare',task);
 PERFORM pg_temp.sa_assert(pid IS NOT NULL AND again->>'planId'=pid,'repeated prepare returns the same saved draft');
 PERFORM pg_temp.sa_assert((SELECT status='draft'AND created_session_id IS NULL FROM journey_hub.session_plans WHERE plan_id=pid),'draft does not publish');
 PERFORM pg_temp.sa_assert((SELECT count(*)=1 FROM journey_hub.staff_agent_events WHERE task_id=task AND kind='draft_prepared'),'one preparation event');
 SELECT version INTO ver FROM journey_hub.session_plans WHERE plan_id=pid;
 res:=public.journeyhub_command('plan',jsonb_build_object('id',pid,'action','save','version',ver,'date',current_date+90,'startTime','14:00','cap',12,'price',1600,'promo',300,'reason','Rollback agent draft edited and submitted for approval'),gen_random_uuid());ver:=(res->>'version')::int;
 res:=public.journeyhub_command('plan',jsonb_build_object('id',pid,'action','submit','version',ver),gen_random_uuid());ver:=(res->>'version')::int;
 res:=public.journeyhub_staff_agent('refresh',NULL);SELECT value INTO item FROM jsonb_array_elements(res->'tasks')WHERE value->>'id'=task::text;
 PERFORM pg_temp.sa_assert(item->>'status'='approval','submission updates persisted assistant state');
 PERFORM pg_temp.sa_assert(item#>>'{evidence,outcome,forecast,con}'=journey_hub.staff_agent_forecast(12,1600,300)->>'con','forecast updates for exact edited draft');
 denied:=false;BEGIN PERFORM public.journeyhub_command('plan',jsonb_build_object('id',pid,'action','approve','version',ver),gen_random_uuid());EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 PERFORM pg_temp.sa_assert(denied,'coordinator cannot self-approve or publish');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',h)::text,true);res:=public.journeyhub_staff_agent('list',NULL);
 PERFORM pg_temp.sa_assert(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(res->'tasks')x WHERE x->>'kind'='opportunity'),'host cannot see finance opportunities');
 denied:=false;BEGIN PERFORM public.journeyhub_staff_agent('prepare',task);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
 PERFORM pg_temp.sa_assert(denied,'host cannot create a planning draft');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',m)::text,true);
 res:=public.journeyhub_command('plan',jsonb_build_object('id',pid,'action','approve','version',ver),gen_random_uuid());sid:=res->>'createdSessionId';
 PERFORM pg_temp.sa_assert(sid IS NOT NULL,'manager publishes canonical session');
 res:=public.journeyhub_staff_agent('list',NULL);SELECT value INTO item FROM jsonb_array_elements(res->'tasks')WHERE value->>'id'=task::text;
 PERFORM pg_temp.sa_assert(item->>'status'='tracking'AND(item#>>'{evidence,outcome,published}')::bool,'assistant verifies exact live publication');
 PERFORM set_config('request.jwt.claims','{}',true);res:=public.journeyhub_snapshot();
 PERFORM pg_temp.sa_assert(EXISTS(SELECT 1 FROM jsonb_array_elements(res->'sessions')x WHERE x->>'session_id'=sid AND x->>'status'='open'),'new session visible in traveler catalogue');
 PERFORM public.journeyhub_demo_wallet_topup(u,100000,gen_random_uuid());PERFORM journey_hub.unified_traveler(u);
 q:=public.journeyhub_demo_session_quote(u,sid,2);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u)::text,true);
 res:=public.journeyhub_command('book',jsonb_build_object('sessionId',sid,'guests',2,'quoteId',q->>'id'),gen_random_uuid());bid:=res->>'id';
 PERFORM pg_temp.sa_assert(bid IS NOT NULL,'traveler creates canonical booking for published session');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',m)::text,true);
 res:=public.journeyhub_staff_agent('refresh',NULL);SELECT value INTO item FROM jsonb_array_elements(res->'tasks')WHERE value->>'id'=task::text;
 PERFORM pg_temp.sa_assert(item#>>'{evidence,outcome,confirmed}'='2'AND item#>>'{evidence,outcome,seatsLeft}'='10'AND item#>>'{evidence,outcome,bookedValueThb}'='3200','published outcome tracks new canonical booking');
 PERFORM pg_temp.sa_assert(EXISTS(SELECT 1 FROM jsonb_array_elements(item#>'{evidence,outcome,bookings}')b WHERE b->>'id'=bid),'outcome references exact canonical booking ID');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u)::text,true);PERFORM public.journeyhub_calendar_manage('booking',bid,'cancel',gen_random_uuid());
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',m)::text,true);
 res:=public.journeyhub_staff_agent('refresh',NULL);SELECT value INTO item FROM jsonb_array_elements(res->'tasks')WHERE value->>'id'=task::text;
 PERFORM pg_temp.sa_assert(item#>>'{evidence,outcome,confirmed}'='0'AND item#>>'{evidence,outcome,cancelled}'='2'AND item#>>'{evidence,outcome,seatsLeft}'='12','cancellation reconciles outcome and restored seats');
 PERFORM pg_temp.sa_assert(item#>>'{evidence,outcome,forecast,con}'=journey_hub.staff_agent_forecast(12,1600,300)->>'con','live cancellation never changes forecast assumptions');
 UPDATE journey_hub.sessions SET starts_at=now()-interval '1 day',ends_at=now()-interval '21 hours'WHERE session_id=sid;
 PERFORM journey_hub.staff_agent_scan();PERFORM journey_hub.staff_agent_scan();
 PERFORM pg_temp.sa_assert((SELECT status='completed'AND task_key='completed:'||id::text FROM journey_hub.staff_agent_tasks WHERE id=task),'completed mission retained');
 PERFORM pg_temp.sa_assert(EXISTS(SELECT 1 FROM journey_hub.staff_agent_tasks WHERE task_key='next-craft-session'AND id<>task AND plan_id IS NULL),'next opportunity generated without publishing or overwriting history');
 SELECT md5(COALESCE(jsonb_agg(to_jsonb(a)ORDER BY experience_id,month,week)::text,''))INTO after_hash FROM journey_hub.activity_weekly_stats a;
 PERFORM pg_temp.sa_assert(before_hash=after_hash,'historical source rows unchanged');
END $$;
SELECT 'PASS staff assistant: durable opportunity, idempotent editable draft, submit, distinct-manager approval, catalog publication, traveler booking/cancellation outcome, roles and unchanged forecasting'AS result;
ROLLBACK;
